defmodule GPUI.Codegen do
  @moduledoc false

  @spec generated_native_element_schema() :: String.t()
  def generated_native_element_schema do
    components = GPUI.ComponentSpec.components()
    elements = GPUI.ComponentSpec.tags()
    styles = GPUI.ComponentSpec.styles()
    events = GPUI.ComponentSpec.events()
    resources = GPUI.ComponentSpec.resources()

    """
    // This file is generated by RustQ. Do not edit by hand.

    pub const GPUI_ELEMENT_TAGS: &[&str] = &[#{rust_string_list(elements)}];
    pub const GPUI_STYLE_ATTRS: &[&str] = &[#{rust_string_list(styles)}];
    pub const GPUI_EVENT_ATTRS: &[&str] = &[#{rust_string_list(events)}];
    pub const GPUI_RESOURCE_TYPES: &[&str] = &[#{rust_string_list(resources)}];

    #{generated_component_specs(components)}

    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub enum GeneratedElementTag {
        Div,
        Button,
        Input,
        Img,
        Text,
        Unknown,
    }

    pub fn decode_generated_element_tag(tag: &str) -> GeneratedElementTag {
        match tag {
    #{rust_match_arms(elements, "GeneratedElementTag")}
            _ => GeneratedElementTag::Unknown,
        }
    }

    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub enum GeneratedResourceType {
        Raster,
        ResourceRef,
        Unknown,
    }

    pub fn decode_generated_resource_type(resource_type: &str) -> GeneratedResourceType {
        match resource_type {
    #{rust_match_arms(resources, "GeneratedResourceType")}
            _ => GeneratedResourceType::Unknown,
        }
    }

    pub fn generated_event_attr_to_type(attr: &str) -> Option<&'static str> {
        match attr {
    #{rust_event_match_arms(components)}
            _ => None,
        }
    }

    pub fn generated_component_kind(tag: GeneratedElementTag) -> GeneratedComponentKind {
        match tag {
    #{rust_component_kind_arms(components)}
            GeneratedElementTag::Unknown => GeneratedComponentKind::Unknown,
        }
    }
    """
  end

  @spec generated_host_commands() :: String.t()
  def generated_host_commands do
    """
    // This file is generated by RustQ. Do not edit by hand.

    #{generated_structs_and_decoders()}

    pub fn dispatch_host_command(op: &str, payload: &Term) -> Term {
        match op {
    #{generated_dispatch_arms()}
            _ => error_reply(format!("unsupported_op:{op}")),
        }
    }
    """
  end

  defp generated_dispatch_arms do
    GPUI.CommandSpec.host_commands()
    |> Enum.map_join("\n", fn {name, spec} ->
      handler = "handle_#{name}"
      decoder = "decode_#{name}"

      if Keyword.get(spec, :args, []) == [] do
        "        \"#{name}\" => #{handler}(),"
      else
        "        \"#{name}\" => match #{decoder}(payload) { Ok(command) => #{handler}(command), Err(reason) => error_reply(reason) },"
      end
    end)
  end

  defp generated_structs_and_decoders do
    GPUI.CommandSpec.host_commands()
    |> Enum.reject(fn {_name, spec} -> Keyword.get(spec, :args, []) == [] end)
    |> Enum.map_join("\n\n", fn {name, spec} ->
      struct_name = rust_struct_name(name)
      fields = Keyword.fetch!(spec, :args)

      field_defs =
        fields
        |> Enum.map_join("\n", fn {field, _type} -> "    pub #{field}: &'a Term," end)

      field_inits =
        fields
        |> Enum.map_join("\n", fn {field, _type} ->
          "        #{field}: required_payload(payload, \"#{field}\")?,"
        end)

      """
      pub struct #{struct_name}<'a> {
      #{field_defs}
      }

      pub fn decode_#{name}<'a>(payload: &'a Term) -> Result<#{struct_name}<'a>, String> {
          Ok(#{struct_name} {
      #{field_inits}
          })
      }
      """
    end)
  end

  defp generated_component_specs(components) do
    kinds = components |> Enum.map(& &1.kind) |> Enum.uniq()

    """
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub enum GeneratedComponentKind {
    #{Enum.map_join(kinds, "\n", &"    #{rust_variant(&1)},")}
        Unknown,
    }
    """
  end

  defp rust_event_match_arms(components) do
    components
    |> Enum.flat_map(& &1.events)
    |> Enum.uniq_by(fn {_event_type, attr} -> attr end)
    |> Enum.map_join("\n", fn {event_type, attr} ->
      ~s|            "#{attr}" => Some("#{event_type}"),|
    end)
  end

  defp rust_component_kind_arms(components) do
    components
    |> Enum.map_join("\n", fn component ->
      ~s|            GeneratedElementTag::#{rust_variant(component.tag)} => GeneratedComponentKind::#{rust_variant(component.kind)},|
    end)
  end

  defp rust_match_arms(values, enum_name) do
    values
    |> Enum.map_join("\n", fn value ->
      ~s|        "#{value}" => #{enum_name}::#{rust_variant(value)},|
    end)
  end

  defp rust_variant(value), do: value |> Atom.to_string() |> Macro.camelize()

  defp rust_string_list(values) do
    values
    |> Enum.map_join(", ", fn value -> ~s("#{value}") end)
  end

  defp rust_struct_name(name) do
    name
    |> Atom.to_string()
    |> Macro.camelize()
    |> Kernel.<>("Command")
  end
end
